// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const NAME_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;
const BULK_UNITS = 100;
const BULK_FACTOR = 0.95;
const LARGE_ORDER = 10000;

// Order here is the order of the sections in the report.
const REGIONS = [
  { code: 'DE', title: 'Germany', taxRate: 0.19 },
  { code: 'FR', title: 'France', taxRate: 0.2 },
  { code: 'UK', title: 'United Kingdom', taxRate: 0.2 },
];

const round2 = (x) => Math.round(x * 100) / 100;

const groupThousands = (digits, separator) => digits.replace(/\B(?=(\d{3})+(?!\d))/g, separator);

export function formatMoney(amount, region) {
  const sign = amount < 0 ? '-' : '';
  const [whole, cents] = Math.abs(amount).toFixed(2).split('.');
  if (region === 'DE') return `${sign}${groupThousands(whole, '.')},${cents} €`;
  if (region === 'FR') return `${sign}${groupThousands(whole, ' ')},${cents} €`;
  if (region === 'UK') return `${sign}£${groupThousands(whole, ',')}.${cents}`;
  throw new Error('unknown region: ' + region);
}

// Net price after discount and bulk rebate, plus VAT, each step rounded to cents.
function grossAmount(sale, taxRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) net -= (net * sale.discountPct) / 100;
  if (sale.units >= BULK_UNITS) net *= BULK_FACTOR;
  net = round2(net);
  return round2(net + round2(net * taxRate));
}

function truncate(name) {
  return name.length > NAME_WIDTH ? name.slice(0, NAME_WIDTH - 1) + '…' : name;
}

function saleLine(sale, amount, region) {
  const line =
    truncate(sale.product).padEnd(NAME_WIDTH) +
    ' ' + String(sale.units).padStart(UNITS_WIDTH) +
    ' ' + formatMoney(amount, region).padStart(MONEY_WIDTH);
  return amount >= LARGE_ORDER ? line + ' *' : line;
}

function validate(options) {
  if (options.format && options.format !== 'text') {
    throw new Error('unsupported format: ' + options.format);
  }
  if (options.month && !/^\d{4}-\d{2}$/.test(options.month)) {
    throw new Error('bad month: ' + options.month);
  }
}

export function buildReport(sales, options = {}) {
  validate(options);
  const { month } = options;
  const lines = [month ? 'SALES REPORT ' + month : 'SALES REPORT', ''];

  const data = sales
    .filter((s) => !month || s.date.slice(0, 7) === month)
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  let rows = 0;
  let large = 0;
  for (const { code, title, taxRate } of REGIONS) {
    const regional = data.filter((s) => s.region === code && s.units > 0);
    if (regional.length === 0) continue;
    lines.push(`== ${title} ==`);
    let subtotal = 0;
    for (const sale of regional) {
      const amount = grossAmount(sale, taxRate);
      lines.push(saleLine(sale, amount, code));
      subtotal += amount;
      rows++;
      if (amount >= LARGE_ORDER) large++;
    }
    lines.push(`Subtotal ${code}: ${formatMoney(subtotal, code)}`, '');
  }

  if (rows === 0) {
    lines.push('No sales.');
  } else {
    lines.push('Rows: ' + rows, 'Large orders: ' + large);
  }
  return lines.join('\n') + '\n';
}
EOF
